begin;

with input_items as (
  select *
  from jsonb_to_recordset('[]'::jsonb) as x(
    id uuid,
    parent_slug text,
    slug text,
    name text,
    item_type text,
    description text,
    sort_order integer,
    metadata jsonb,
    is_active boolean
  )
),
resolved_items as (
  select
    i.id,
    p.id as parent_id,
    i.slug,
    i.name,
    i.item_type::internal_knowledge_item_type as item_type,
    nullif(i.description, '') as description,
    i.sort_order,
    i.metadata,
    coalesce(i.is_active, true) as is_active
  from input_items i
  left join public.internal_knowledge_feature_items p on lower(p.slug) = lower(i.parent_slug)
)
insert into public.internal_knowledge_feature_items (
  id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, updated_at
)
select id, parent_id, slug, name, item_type, description, sort_order, metadata, is_active, now()
from resolved_items
on conflict (id) do update set
  parent_id = excluded.parent_id,
  slug = excluded.slug,
  name = excluded.name,
  item_type = excluded.item_type,
  description = excluded.description,
  sort_order = excluded.sort_order,
  metadata = public.internal_knowledge_feature_items.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

with input_blocks as (
  select *
  from jsonb_to_recordset('[{"id": "a37db752-3167-5870-b453-561d3f34d471", "feature_slug": "cs-ai-system-feature-spec", "title": "4. AI AGENT", "content": "### 4.1 Knowledge Library\n\n**Content Sources (unstructured — for semantic search via pgvector):**\n- Upload documents: PDF, DOCX, TXT, CSV\n- Website scraper: crawl brand website, product pages, FAQ pages\n- Help center integration: import existing help articles\n- Manual entries: write Q&A pairs directly\n- Product catalog sync: import from Shopee/Lazada/Shopify (name, description, specs — as text articles for semantic search)\n- API connector: pull knowledge from external CMS or knowledge base\n\n**Structured Data Access (for exact queries — via MCP tools, NOT knowledge base):**\n- Product catalog queries: `@Search Products` with filters (category, price, skin_type, in_stock) → queries local product table or live marketplace API\n- Order lookups: `@Lookup Order` → queries marketplace API directly (always live, never cached)\n- Account details: `@Get Customer Profile` → queries CRM bridge\n- Policy lookups: `@Check Policy` with product_category → queries policy table\n- Rule: unstructured knowledge (descriptions, FAQs, guides) → embed and vector search. Structured data (orders, prices, stock, policy tables) → MCP tool queries.\n\n**Product Catalog Strategy — Separate Knowledge from Platform Listings**\n\nInspired by [Gorgias](https://docs.gorgias.com/en-US/manage-your-product-information-for-ai-agent-4036592) (syncs product data locally from Shopify + crawls website + custom info).\n\n**Multi-platform challenge:** \"Collagen 360 Cream\" is `item_id: SH_123` on Shopee, `LZ_456` on Lazada, `TT_789` on TikTok. Same product, different IDs, different prices.\n\n**Solution: split product knowledge (platform-agnostic) from platform listings (platform-specific).**\n\n| Data | Where It Lives | How AI Accesses | Why |\n|---|---|---|---|\n| Product knowledge (descriptions, ingredients, specs, usage) | **CS AI knowledge base** — one article per product, platform-agnostic | Vector search (pgvector) | Rarely changes. Needed for semantic search (\"what''s good for oily skin?\"). Can''t vector-search a live API. Synced from brand website or uploaded by brand. |\n| Price, stock, availability | **Platform** — queried live | `@Get Product Price` / `@Check Stock` MCP tool → calls the marketplace API for whichever platform the conversation is on | Changes frequently. Must be real-time. |\n| Orders, status, tracking | **Platform** — queried live | `@Lookup Order` MCP tool → marketplace API | Always transactional. Always real-time. |\n\nThe AI knows which platform the conversation is on (from the channel/conversation record) and calls the right platform API. No master product table with cross-platform ID mapping needed.\n\nProduct knowledge sync runs daily or on webhook. Synced content auto-chunked and embedded by the Supabase automatic embedding pipeline.\n\n**Knowledge Management:**\n- Organize by categories/folders (Products, Policies, Shipping, Returns, etc.)\n- Version control: track changes, rollback\n- Per-brand knowledge isolation (multi-tenant: Brand A knowledge never leaks to Brand B)\n- Knowledge gap detection: AI identifies questions it couldn''t answer and suggests content to create (like Decagon''s Suggestions)\n- Knowledge freshness: flag stale content, auto-detect when source URL changes\n- Priority: admin can mark certain content as authoritative (always preferred over general knowledge)\n\n**Custom Answers (Override AI):**\n- For specific questions, admin writes exact answer to use instead of AI-generated response\n- Supports rich media: images, links, buttons\n- Conditional: different answer based on customer segment, platform, language\n- Higher priority than AI-generated responses\n- Training: provide 10+ example question variations per answer so AI recognizes different phrasings\n- Temporary answers: quick to create and delete for temporary issues (product recalls, outages, promotions) — like Intercom''s Snippets concept\n\n**Guidance Rules (Fine-Tuning AI Behavior):**\n- Natural language instructions that shape how the AI behaves across all conversations (unlike Procedures which are per-topic)\n- Organized by category:\n  - **Communication style**: tone, terminology, formality level, emoji usage, response length — \"speak like our best-trained agent\"\n  - **Context and clarification**: when and how the AI should ask follow-up questions before answering — \"always ask for order number before looking up order status\"\n  - **Content and sources**: which knowledge sources the AI should prefer or avoid for specific topics — \"for ingredient questions, always reference the product spec sheet, not the marketing page\"\n  - **Escalation rules**: when to hand off — \"if customer mentions legal action, escalate immediately\"\n  - **Spam handling**: how to detect and handle spam/bot messages\n  - **Sensitive topics**: what not to discuss, how to redirect\n- Guidance effectiveness reporting: AI tracks how well it follows each guidance rule, surfaces which rules are being ignored or causing issues\n- AI-suggested guidance improvements: based on conversation patterns, AI suggests new rules — \"customers asking about ingredient X are frequently unsatisfied with the current answer — consider adding more detail\"\n\n### 4.2 Customer Context\n\n**Context is lazy-loaded — not all data goes into every prompt.**\n\nThree tiers:\n\n**Always loaded (small, cheap — every prompt):**\n- Customer profile: name, language, tier, tags (a few lines)\n- Current conversation: last 10-20 messages\n- Active ticket: status, type, priority\n- Customer memory: key-value pairs from past interactions (see 4.3)\n\n**Loaded on demand (fetched only when an AOP step needs it):**\n- Order data: only when procedure step calls `@Lookup Order` — fetches the specific order being discussed, not all orders ever\n- Loyalty data: only when relevant — fetched via CRM bridge when customer asks about points/tier/rewards\n- Product details: only when answering product questions — fetched via vector search or `@Get Product Details`\n\n**Never loaded into prompt (too large):**\n- Full past conversation transcripts — replaced by distilled memory (see 4.3)\n- Full order history — queried on demand via MCP tools\n- Full product catalog — searched via vector search or MCP query\n\n**Customer Identity Resolution:**\n- Match across platforms by phone number, email, or LINE user ID\n- Manual linking by agent (confirm \"is this the same person?\")\n- Automatic suggestion: \"This Shopee buyer has the same phone as this LINE user — link?\"\n- Unified profile view across all linked identities\n\n### 4.3 Conversation Memory\n\n**Short-term memory**: full conversation context within the current session. All messages in the current conversation are in the prompt. Standard — every chat system does this.\n\n**Long-term memory**: persistent, distilled signals about a customer across sessions (like Decagon User Memory). This is NOT storing full past transcripts — it''s storing extracted facts.\n\n**How memory is created (the distillation process):**\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_AI_System.md#L5 4. AI AGENT", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-ai-system-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a1494e2b552191af33ca28ef2083f0fed8f0ab70d905996b3b13cbb954827514", "truncated": true}, "is_active": true}, {"id": "47fa813a-e691-58ba-a38f-c429ea00937f", "feature_slug": "cs-ai-system-feature-spec", "title": "CS AI System (Feature Spec) Domain Reference", "content": "**Keywords:** knowledge_library, customer_context, conversation_memory, agent_reasoning, guardrails, brand_voice, aop, procedure, copilot, testing, simulation, a_b_test, versioning, flywheel, multi_model, intent_understanding, hallucination, supervisor_verification\n**Source:** `CS_AI_System.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-ai-system-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-ai-system-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "556ef4f78413831e5830c779d90a41f785db3f83f1f84502b2d4ccf8856a2722", "truncated": false}, "is_active": true}, {"id": "4783a0c3-d5cf-57a8-b15f-87397a71f78d", "feature_slug": "cs-analytics-qa-feature-spec", "title": "7. ANALYTICS AND INSIGHTS", "content": "### 7.1 Operational Metrics\n\n- Total conversations (by channel, brand, time period)\n- Average first response time\n- Average resolution time\n- AI resolution rate (% resolved without human)\n- Human escalation rate and reasons\n- Conversations per agent (workload distribution)\n- SLA compliance rate\n- Busiest hours / days heatmap\n- Queue depth over time\n\n### 7.2 AI Performance\n\n- AI resolution rate by intent type (refund: 85%, product question: 92%, complaint: 40%)\n- AI confidence score distribution\n- Hallucination rate (detected via QA)\n- **Unresolved questions report** (inspired by Intercom Fin):\n  - Auto-groups unresolved questions by topic (AI-generated topic names)\n  - Shows volume per topic group, trend over time\n  - Breakdown: AI didn''t know the answer vs. customer requested human vs. conversation abandoned vs. negative feedback\n  - \"Related content\" view: shows which knowledge sources the AI attempted to use (helps identify if the content exists but is insufficient vs. missing entirely)\n  - Drill into individual conversations per topic group\n  - One-click: create knowledge article or custom answer directly from an unresolved topic\n  - Filter by language, channel, brand\n- Action success/failure rates\n- Average AI response time (latency)\n- Cost per resolution (LLM token cost + action cost)\n\n### 7.3 Customer Insights\n\n- Top customer intents (what are people asking about most)\n- Sentiment trend over time\n- Repeat contact rate (customers who come back for same issue)\n- CSAT scores by channel, agent, intent, brand\n- Customer effort score\n- Feature request extraction: AI identifies and aggregates feature requests from conversations\n- Product feedback extraction: AI identifies product complaints and compliments\n\n### 7.4 Quality Assurance\n\n- **Auto QA**: AI evaluates 100% of conversations (not just a sample) against configurable quality criteria\n- **Configurable scorecards**: define scoring criteria per brand or team:\n  - Accuracy: did the agent/AI give correct information?\n  - Tone: was the response on-brand and empathetic?\n  - Policy compliance: did the agent follow the defined procedure?\n  - Resolution quality: was the issue actually resolved?\n  - Empathy and effort: did the agent acknowledge the customer''s frustration?\n  - Technical accuracy: for product/technical questions, was the answer factually correct?\n  - Custom criteria: add brand-specific scoring dimensions\n- Scorecard scores: overall score, pass rate, per-criteria breakdown\n- Score trends over time: are scores improving or degrading? (per agent, per AI, per team)\n- QA scorecards: per-agent and per-AI performance side by side\n- Flagged conversations: auto-surface conversations that need review (low confidence, negative sentiment, policy deviation, low QA score)\n- **AI-generated CSAT prediction**: AI predicts customer satisfaction from conversation content without needing an explicit survey (useful when survey response rate is low)\n- Coaching insights: identify patterns where specific agents need improvement, with timestamped examples linking to coachable moments\n- AI self-improvement: conversations where AI was corrected feed back into training\n- Quality comparison: AI agent quality vs. human agent quality on the same scorecard dimensions\n\n### 7.5 Watchtower (Always-On Monitoring)\n\nInspired by [Decagon''s Watchtower](https://decagon.ai/product/watchtower). A configurable monitoring layer that continuously reviews every conversation — AI and human — against custom criteria, surfacing what matters without manual QA overhead.\n\n**Natural Language Monitoring Criteria:**\n- Define what to watch for in plain language, not keywords:\n  - \"Customer expresses frustration or anger\"\n  - \"Agent promises a refund or discount outside of policy\"\n  - \"Customer mentions a competitor product\"\n  - \"Conversation involves a data privacy or legal concern\"\n  - \"Customer signals purchase intent or upsell opportunity\"\n  - \"AI hallucinated or gave incorrect product information\"\n  - \"Customer has contacted more than 3 times about the same issue\"\n- The system interprets intent contextually (LLM-based evaluation), not keyword matching\n- Multiple Watchtower monitors can run simultaneously (one for compliance, one for sales signals, one for product feedback, etc.)\n\n**Scoping and Filters:**\n- Filter which conversations to monitor: by channel, brand, agent (human or AI), CSAT score, resolution status, customer tier, language, time range\n- Continuous mode: monitor all new conversations in real-time going forward\n- Historical mode: run a monitor against past conversations to surface retroactive insights (e.g., \"how many data privacy issues did we have last month?\")\n\n**Auto-Categorization:**\n- Flagged conversations are automatically grouped into meaningful clusters\n- Example clusters: \"data privacy violations\", \"purchase intent\", \"product defect reports\", \"shipping complaints\", \"competitor mentions\"\n- Categories are AI-generated based on the flagged content, not pre-defined\n\n**Rubric Scoring:**\n- Define multiple scoring fields per Watchtower (e.g., \"accuracy: 1-5\", \"empathy: 1-5\", \"policy compliance: pass/fail\")\n- Each field has its own scoring scale and point values\n- Track average scores over time — per agent, per AI, per team, per brand\n- Detect score trends: \"Agent X''s empathy score has dropped 15% this week\"\n\n**Alerting:**\n- Real-time alerts when critical criteria are flagged (e.g., \"legal concern detected\" → immediately notify supervisor via Slack/LINE Notify)\n- Alert thresholds: \"If more than 5 compliance flags in one hour, alert the compliance team\"\n- Escalation: auto-assign flagged conversations to a supervisor for review\n\n**Dashboards and Drilldown:**\n- Real-time trend dashboard: flag volume over time, by category, by severity\n- Click from a trend line into individual flagged conversations with full transcript and context\n- Cross-reference with CSAT: \"Do flagged conversations correlate with low CSAT?\"\n\n**Beyond QA — Business Intelligence:**\n- Product feedback extraction: \"Which product gets the most complaints and why?\"\n- Feature request aggregation: \"What are customers asking for that we don''t offer?\"\n- Conversion signal detection: \"Which conversations showed purchase intent that we missed?\"\n- Competitive intelligence: \"What are customers saying about competitor products?\"\n- Churn risk detection: \"Which customers are showing signs of leaving?\"\n\n### 7.6 CSAT Surveys\n\n- Auto-trigger survey after conversation resolution\n- Configurable survey: 1-5 stars, thumbs up/down, NPS, free text\n- Per-channel survey format (LINE quick reply, email link, in-chat widget)\n- Results linked to conversation for drill-down analysis\n- Alert on low CSAT: notify supervisor in real-time", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Analytics.md#L5 7. ANALYTICS AND INSIGHTS", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-analytics-qa-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "37cab9084a5a1762476f257c41273ee8fd9e4310afed88524c25e9e8169c9193", "truncated": false}, "is_active": true}, {"id": "33ff3cd0-4f98-58df-87c2-b875cc382899", "feature_slug": "cs-analytics-qa-feature-spec", "title": "CS Analytics & QA (Feature Spec) Domain Reference", "content": "**Keywords:** analytics, metrics, resolution_rate, csat, watchtower, auto_qa, scorecard, sentiment, unresolved_questions, knowledge_gap, coaching, nps, hallucination_rate\n**Source:** `CS_Analytics.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-analytics-qa-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-analytics-qa-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ca3d060ad24b0d69dad7d28420b5fbae6d7e4baab4060494dc108262fe32fc26", "truncated": false}, "is_active": true}, {"id": "53f1c1a6-c7de-5edf-bbb5-0f723b3a1f30", "feature_slug": "cs-brand-configuration", "title": "DATABASE SCHEMA DESIGN — CS Module", "content": "This section covers the conceptual model, naming conventions, and table schemas for the CS module. These are decisions that affect every feature built on top.\n\n---\n\n### 1. Conceptual Framework\n\n#### 1.1 The CS AI is a Composition, Not an Agent\n\nThe CRM''s marketing AI (`amp_agent`) is an **autonomous decision-maker** — it has objectives (drive_purchase), KPIs, deliberation cycles, and chooses actions independently. It IS an agent.\n\nThe CS AI is fundamentally different. It is an **orchestrated composition** of independent components:\n\n```\nCS AI behavior at runtime =\n    Brand config (voice, tone, language, model)        — from cs_brand_config\n  + Guardrails (topic rules, escalation triggers)      — from cs_brand_config + procedure + action config\n  + Knowledge (articles, embeddings)                   — from cs_knowledge_articles\n  + Procedure (step-by-step AOP for this intent)       — from cs_procedures\n  + Available tools (with per-tool constraints)         — from cs_brand_config.action_config\n  + Customer memory (cross-session facts)              — from cs_customer_memory\n  + Conversation context (messages, history)            — from cs_conversations + cs_messages\n```\n\nNo single \"agent\" entity owns all of this. The components are independent, each with their own lifecycle and table. They converge on the **conversation** at runtime.\n\n**Why this matters for schema design**: There is no `cs_agent` table. The AI behavior emerges from composing components, not from configuring a standalone entity.\n\n#### 1.1b Multi-Model Pipeline (\"Sub-Agents\") — Infrastructure, Not Entities\n\nSierra, Decagon, and (to a lesser degree) Intercom all describe \"sub-agents\" or \"specialized models.\" This is often misunderstood as separate configurable agents per topic. It is not. It is **multi-model orchestration within a single processing pipeline** — different models handling different computational tasks per request.\n\n**Sierra''s \"constellation of models\"** (15+ models per agent):\n\n| Pipeline stage | Specialized for | Model type |\n|---|---|---|\n| Intent/classification | Fast, high-precision categorization | Small fine-tuned model |\n| Tool calling | Low-latency API decisions (orders, inventory) | Fast model with tight latency constraints |\n| Long-context reasoning | Complex policies, dense info, multi-step logic | Large frontier model (high reasoning) |\n| Tone/voice generation | On-brand, warm, conversational output | Fine-tuned or prompted for brand voice |\n| Supervisor (\"Jiminy Cricket\") | Validates actions, enforces guardrails, catches errors | Separate model with independent evaluation |\n\n**Decagon''s \"specialized model network\"** (80%+ proprietary models):\n\n| Pipeline stage | Specialized for | Training method |\n|---|---|---|\n| Intent classifier | What does the customer want? | Fine-tuned (SFT + RL) |\n| Workflow executor | Follow AOP steps, generate response | Fine-tuned on conversation data |\n| Hallucination detector | Check response before sending | Fine-tuned classifier |\n| Bad actor detector | Screen for manipulation, adversarial prompts | Fine-tuned at conversation start |\n| Escalation decider | Should this go to a human? | Fine-tuned on escalation patterns |\n\n**Intercom Fin**: Single-agent system. No multi-model orchestration. Simpler but less optimizable.\n\n**Key distinction**: These \"sub-agents\" are invisible to the CX team. They don''t configure them. They don''t create them. They''re infrastructure that the platform manages. The CX team configures ONE thing per brand (voice, guardrails, knowledge, procedures) and the platform decides which model handles which stage.\n\n**How this maps to our architecture — the processing pipeline:**\n\n```\nMessage arrives\n    → [Stage 1: Bad Actor Screening]     — fast classifier, runs in parallel\n    → [Stage 2: Intent Classification]   — fast model (GPT-4o-mini or fine-tuned)\n    → [Stage 3: Knowledge Retrieval]     — embedding model + pgvector similarity search\n    → [Stage 4: Main Reasoning]          — powerful model (GPT-4o / Claude), follows procedure\n    → [Stage 5: Response Generation]     — same model or tone-specific model\n    → [Stage 6: Hallucination Check]     — separate model validates factual accuracy\n    → [Stage 7: Supervisor Verification] — for high-risk actions only (refunds, cancellations)\n    → Send response\n```\n\n**Where this lives in the schema**: Not in separate tables — in `cs_brand_config.model_config`:\n\n```json\n{\n  \"intent_model\": {\"provider\": \"openai\", \"model\": \"gpt-4o-mini\"},\n  \"reasoning_model\": {\"provider\": \"anthropic\", \"model\": \"claude-sonnet-4\"},\n  \"embedding_model\": {\"provider\": \"openai\", \"model\": \"text-embedding-3-small\"},\n  \"verification_model\": {\"provider\": \"openai\", \"model\": \"gpt-4o-mini\"},\n  \"hallucination_check_enabled\": true,\n  \"bad_actor_screening_enabled\": true,\n  \"supervisor_verification\": {\n    \"enabled\": true,\n    \"for_action_types\": [\"process_refund\", \"cancel_order\", \"account_change\"]\n  }\n}\n```\n\nNo new tables for the multi-model pipeline. It''s an execution concern handled in the AI service code (Render). The database stores which models and which stages are enabled.\n\n#### 1.1c Our Approach: Context Injection on General LLMs (Not Specialized Models)\n\nSierra and Decagon achieve precision by **fine-tuning small specialized models** — one for intent classification, one for hallucination detection, one for escalation, etc. Each model is trained on millions of real conversations using supervised fine-tuning (SFT) and reinforcement learning (RL). The result: each model is an expert at its one job, fast, cheap per call, and highly accurate.\n\nWe cannot start there. Fine-tuning requires:\n- Millions of labeled conversations (we have zero at launch)\n- ML engineering team to train, evaluate, and maintain each model\n- Infrastructure for model serving, versioning, A/B testing models\n- Months of iteration per model\n\n**Our approach: one general-purpose LLM + context injection.** Instead of training a specialized model for each task, we inject the right context into one powerful model''s prompt and let it handle everything.\n\n**How it works — same pipeline stages, different execution:**\n\n| Pipeline stage | Sierra/Decagon approach | Our approach (Phase 1) |\n|---|---|---|\n| **Intent classification** | Fine-tuned classifier → returns `refund_request` in ~50ms | Same LLM, first call with a classification prompt: \"Given this message, classify the intent.\" ~200ms. Or use a structured output schema. |\n| **Knowledge retrieval** | Proprietary RAG with fine-tuned reranker | pgvector semantic search + OpenAI embeddings. Standard RAG. Same architecture, off-the-shelf models. |\n| **Main reasoning** | Fine-tuned model trained on successful resolutions | General frontier model (GPT-4o / Claude) with full context injected: brand config + procedure + knowledge chunks + customer memory + guardrails. The prompt IS the specialization. |\n\n_Source section truncated in seed output; consult `source_ref` for the full text._", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Feature_Spec.md#L2 DATABASE SCHEMA DESIGN — CS Module", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-brand-configuration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "ce85245d2d366686561d98b2e92adc6bb3271e7eb2d297c5050ed6d709f6709d", "truncated": true}, "is_active": true}, {"id": "5bfe0328-0799-50ed-b427-85f0d52bb13b", "feature_slug": "cs-brand-configuration", "title": "CS Brand Configuration Domain Reference", "content": "**Keywords:** brand_config, voice, tone, guardrails, model_config, action_config, outbound, cs_brand_config, voice_preset, forbidden_phrases, escalation_triggers\n**Source:** `CS_Feature_Spec.md` (section 4.1)\n**Tables:** `cs_brand_config`\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_brand_config` | BFF | Get brand AI configuration |\n| `cs_bff_upsert_brand_config` | BFF | Update brand AI configuration |\n**Key Business Rules (summary):**\n- One row per merchant (UNIQUE on merchant_id)\n- Guardrails are distributed: brand-level in this table, per-procedure in `cs_procedures`, per-action in `action_config`\n- Override chain: procedure config > channel config > brand config\n- Model pipeline stages configured in `model_config` JSONB (intent, reasoning, embedding, verification models)", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-brand-configuration.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-brand-configuration", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "70fb110b3ff044752c8225fbd77e966292fc9adcf05dcf8fd4595accf96c8eda", "truncated": false}, "is_active": true}, {"id": "1ecf1179-2545-5e1a-975f-756a12211998", "feature_slug": "cs-channel-connectors-feature-spec", "title": "1. CHANNEL CONNECTORS", "content": "### 1.1 Marketplace Chat\n\n**Shopee Chat**\n- Receive buyer messages via webhook (real-time)\n- Send text replies\n- Send product cards (via item_id)\n- Send order cards (via order_id)\n- Send voucher/promotion cards (via promotion_id)\n- Read conversation history (last 90 days via API)\n- Requires: Shopee Open Platform whitelisted partner access\n\n**Lazada Chat**\n- Same capabilities as Shopee (send/receive text, product cards, order cards, voucher cards)\n- Open Platform API (lower barrier than Shopee)\n- Conversation history: 90 days\n\n**TikTok Shop Chat**\n- Send/receive text, images, videos\n- Product and order cards (likely supported via API)\n- Webhook events: NEW_MESSAGE, NEW_CONVERSATION\n- 12-hour response rate SLA enforced by platform\n\n**Common marketplace features:**\n- Message rate limit handling and retry logic\n- Platform-specific message format adaptation\n- Delivery status tracking (sent, delivered, read where available)\n- Session timeout handling (Shopee: 7 days inactive, TikTok: 7 days)\n\n### 1.2 Messaging Platforms\n\n**LINE OA**\n- Messaging API: text, flex messages, rich menus, quick replies, image maps\n- Push messages (proactive outreach)\n- Webhook for incoming messages\n- LINE Login for customer identity\n- Rich menu management per brand\n\n**Facebook Messenger**\n- Send/receive text, images, quick replies, buttons, carousels\n- Persistent menu\n- Handover protocol (switch between bot and human)\n- Webhook for incoming messages\n\n**Instagram DM**\n- Send/receive text, images, story replies\n- Quick replies\n- Ice breakers (conversation starters)\n\n**WhatsApp Business API**\n- Send/receive text, images, documents, location\n- Template messages (pre-approved for outbound)\n- Interactive messages (list, button, product)\n- 24-hour messaging window rules\n- Catalog integration\n\n**Email**\n- IMAP/SMTP or Gmail/Outlook API integration\n- Thread detection and conversation grouping\n- HTML rendering for rich email replies\n- Attachment handling\n- Signature management per brand\n\n### 1.3 Web Chat Widget\n\n- Embeddable JavaScript widget for brand websites\n- Customizable: colors, position, avatar, greeting message\n- Pre-chat form (name, email, topic)\n- File/image upload from customer\n- Typing indicators\n- Chat transcript download for customer\n- Proactive triggers (time on page, exit intent, specific URL)\n\n### 1.4 Voice\n\n**Inbound Voice**\n- SIP trunk integration (Twilio, local Thai telco)\n- IVR menu (press 1 for X) — optional, can go straight to AI\n- AI picks up the call, converses naturally\n- Speech-to-Text: streaming real-time (Typhoon Whisper for Thai, Deepgram/Whisper for English)\n- Text-to-Speech: natural voice output (ElevenLabs or Gowajee for Thai)\n- DTMF tone detection (for entering account numbers)\n- Call recording with transcription\n- Hold music / transfer music\n- Warm transfer to human with AI-generated summary\n\n**Outbound Voice**\n- Campaign-based: upload list, define script, schedule\n- Event-triggered: appointment reminder, payment due, delivery follow-up\n- Voicemail detection: leave message or retry later\n- Robocall screener handling\n- Call outcome logging (answered, voicemail, no answer, busy)\n- Compliance: time-of-day restrictions, do-not-call list\n\n**Voice-specific AI features:**\n- Barge-in handling (customer interrupts AI mid-sentence)\n- Silence detection (customer not responding)\n- Background noise tolerance\n- Code-switching (Thai-English mixed speech)\n- Tone/sentiment detection from voice\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Channel_Connectors.md#L5 1. CHANNEL CONNECTORS", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-channel-connectors-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "936b2a663043815982d84d720f89a57146770457d6c68bcc66ab8e15f2eec69b", "truncated": false}, "is_active": true}, {"id": "2ea2b1ba-4deb-5cc5-973d-60bcb7a2a654", "feature_slug": "cs-channel-connectors-feature-spec", "title": "CS Channel Connectors (Feature Spec) Domain Reference", "content": "**Keywords:** shopee_chat, lazada_chat, tiktok_chat, line_oa, whatsapp_business, facebook_messenger, instagram_dm, email, web_widget, voice, inbound_voice, outbound_voice, sip, stt, tts, webhook, rich_menu, flex_message, template_message\n**Source:** `CS_Channel_Connectors.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-channel-connectors-feature-spec.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-channel-connectors-feature-spec", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "412243cf6541beaea9c96a875d542509860509cdfb6dd1ca8152e09a2c8c8b4f", "truncated": false}, "is_active": true}, {"id": "ab9e9991-0368-59bb-a35f-b4bbb8667a07", "feature_slug": "cs-channels", "title": "4. Admin Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| Channel List | `/cs-channels` | `cs_bff_get_channels()` |\n| Channel Config (new) | `/cs-channels/new` | Platform selector → credential form |\n| Channel Config (edit) | `/cs-channels/{id}` | `merchant_credentials` direct query |\n| Contact List | `/cs-customers` | `cs_contacts` direct table read |\n| Contact Detail | `/cs-customers/{id}` | `cs_bff_get_contact_details()` |\n| Integration Hub | `/integration` | `bff_get_integration_config()` |\n\n### 4a. Connect a New Channel\n\n1. From **Channel List**, click **\"Connect channel\"** button (or empty state CTA)\n2. **Channel Config** opens — **Platform Selector** shows all 10 channel types grouped by category (Marketplace, Messaging, Other) as selectable cards\n3. Select a platform → credential form renders dynamically based on the channel type\n4. For *oauth* channels (Shopee, Lazada, TikTok): redirect to platform authorization flow\n5. For *credentials* channels: fill in platform-specific fields (tokens, IDs, secrets)\n6. For *web_widget*: no credentials needed — auto-generated embed code\n7. Set channel display name and scope (defaults to `{cs}`)\n8. Configure behavior settings: session timeout, threading interval, auto-reply, AI toggle\n9. Click **\"Save\"** → credential saved to `merchant_credentials`, health set to `disconnected`\n10. Run **\"Test connection\"** to verify → health updates to `healthy` on success\n\n### 4b. Manage Channel List\n\n1. **Channel List** displays cards grouped by category (Marketplace, Messaging, Other)\n2. Each card shows: platform icon (color-coded), display name, channel type label, health badge, active/inactive status, last checked timestamp, AI badge if enabled\n3. **Filters**: search by name/type, filter by channel type (multi-select), filter by health status (multi-select)\n4. **Stats banner**: Connected count, Healthy count, Needs Attention count (shown only if > 0)\n5. Click any card → navigates to **Channel Config** edit page\n6. Card menu (three-dot): Edit settings, Test connection, Disconnect/Activate\n\n### 4c. View Contact Details\n\n1. From **Contact List**, click a contact row → **Contact Detail** opens\n2. Shows: contact profile (name, email, phone, language, tags, custom fields), all linked platform identities, customer memory entries, recent 10 conversations\n3. Agent can manually link/unlink platform identities, edit contact fields, delete memory entries\n\n### 4d. Common Admin Mistakes\n\n- Entering expired or revoked tokens → health stays `disconnected`, no error detail until test\n- Setting scope to `{earn}` only → channel won''t appear in CS channel list\n- Forgetting to test connection after saving → messages won''t route until health is verified\n- Leaving AI enabled on a channel without configuring the AI agent → messages go to AI with no instructions", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-channels.md#L78 4. Admin Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "cc82b12cbc489f082883a2bb540f5c6832c879576ab683fbf2620d40a67b9bdb", "truncated": false}, "is_active": true}, {"id": "f5b21222-b4aa-58f2-9b7e-38323ad9ea96", "feature_slug": "cs-channels", "title": "7. Business Rules", "content": "**Rule:** One unified contact per person per merchant. Multiple platform identities point to the same `cs_contacts` row. Cross-merchant contacts are fully isolated.\n**Example:** A person messaging from LINE and Shopee for Merchant A = one contact. The same person messaging Merchant B = a separate contact.\n\n**Rule:** Identity resolution is automatic on every inbound message. The lookup key is `(platform_type, platform_user_id, merchant_id)`.\n**Example:** Shopee buyer \"abc123\" sends a message → system queries `cs_platform_identities` → found → routes to existing contact.\n\n**Rule:** Cross-platform linking requires matching phone, email, or manual agent confirmation. The system auto-suggests but does not auto-merge.\n**Example:** Shopee buyer has phone +66812345678, same as existing LINE contact → system suggests link, agent confirms.\n\n**Rule:** `crm_user_id` is nullable. CS operates independently from the loyalty module. When linked, loyalty data (tier, points, history) enriches the agent workspace.\n**Example:** Contact without `crm_user_id` → agent sees conversation history and memory only. With `crm_user_id` → agent also sees loyalty tier and point balance.\n\n**Rule:** Customer memory has configurable expiration (default 1 year). Expired memory is auto-deleted. Contradicting facts overwrite previous entries.\n**Example:** Memory `{key: \"skin_type\", value: \"oily\"}` → customer later says \"my skin has become dry\" → value updates to \"dry\".\n\n**Rule:** Memory extraction is async — runs after conversation resolves, not during. Uses a separate LLM call on the transcript.\n**Example:** 30-message conversation resolves → LLM extracts 3 memory entries → stored in `cs_customer_memory`.\n\n**Rule:** Credential scope controls module visibility. Only credentials with `scope && ARRAY[''cs'']` appear in the CS channel list. A credential can serve multiple modules simultaneously.\n**Example:** LINE OA with `scope = ''{earn,cs}''` → visible in CS Channels and in Earn channel config.\n\n**Rule:** Marketplace channels enforce platform-specific session timeouts. Shopee and TikTok: 7 days inactive. WhatsApp: 24-hour messaging window for outbound.\n**Example:** WhatsApp customer last messaged 25 hours ago → merchant cannot send free-form message, must use approved template.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L242 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c2b6e75e817309fc396af13cc5fa61d0caa2416331ae65ecaecea122ce5d7dbd", "truncated": false}, "is_active": true}, {"id": "ec9eea97-8ad0-514b-8c32-94a6b6ad3251", "feature_slug": "cs-channels", "title": "3. Configuration Reference", "content": "### Channel Credentials (per channel type)\n\n| Channel Type | Required Fields | Connect Method |\n|---|---|---|\n| Shopee | OAuth flow (no manual fields) | `oauth` |\n| Lazada | OAuth flow | `oauth` |\n| TikTok Shop | OAuth flow | `oauth` |\n| LINE Official | Channel Access Token, Channel Secret | `credentials` |\n| WhatsApp Business | Phone Number ID, Permanent Access Token, WABA ID | `credentials` |\n| Facebook Messenger | Page Access Token, App ID, Page ID | `credentials` |\n| Instagram DM | Page Access Token, Instagram Account ID | `credentials` |\n| Email | Email Address, IMAP Host/Port, SMTP Host/Port, Password | `credentials` |\n| Web Chat Widget | None (auto-generated) | `auto` |\n| Voice (SIP) | Twilio Account SID, Auth Token, Phone Number | `credentials` |\n\n### Behavior Settings\n\n| Setting | What it controls | Options | Default |\n|---|---|---|---|\n| Session timeout | Auto-close idle conversations | 15min, 30min, 1h, 4h, 12h, 24h, 48h | — |\n| Threading interval | Group messages into same thread | 1h, 6h, 12h, 24h, 48h, 72h | — |\n| Auto-reply enabled | Send automatic response on first message | Toggle | Off |\n| Auto-reply message | Text of the automatic response | Free text | — |\n| AI enabled | Route to AI agent before human | Toggle | Off |\n| Voice preset override | Custom voice profile for voice channels | Select | — |\n\n### Phone Number Management (Voice/SMS)\n\n| Setting | What it controls | Example |\n|---|---|---|\n| Provider | Telephony provider account | Twilio (BYOT or master subaccount) |\n| Phone number | E.164 format number | +66812345678 |\n| Capabilities | What the number supports | `{voice, sms}` |\n| Friendly name | Merchant label | \"Main Support Line\" |", "content_format": "markdown", "knowledge_type": "configuration_reference", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-channels.md#L41 3. Configuration Reference", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "43db4b9cd2da2870b483397b3a40fbeaddee359f60225610bd11cbdac0b9a5e1", "truncated": false}, "is_active": true}, {"id": "4a54f578-1532-5248-bfda-aa0dbf142e18", "feature_slug": "cs-channels", "title": "2. Key Concepts", "content": "**Channel** — A connected messaging platform configured with credentials and behavior settings. Stored as a row in `merchant_credentials` with `scope` including `cs`. Example: \"LINE OA: @mesoestetic_th\" with channel access token and session timeout of 30 minutes.\n\n**Channel Type** — One of 10 supported platforms, organized into three categories: *marketplace* (shopee, lazada, tiktok), *messaging* (line, whatsapp, facebook, instagram), and *other* (email, web_widget, voice).\n\n**Connect Method** — How a channel authenticates: `oauth` (marketplace channels — redirect flow), `credentials` (messaging/voice — manual token entry), or `auto` (web widget — no credentials needed).\n\n**Health Status** — Connection state of a channel: `healthy` (working), `degraded` (intermittent issues), `disconnected` (not connected or deactivated), `error` (broken, needs attention).\n\n**Contact** — A unified person record (`cs_contacts`) combining all platform identities for one individual under one merchant. Holds display name, email, phone, language, tags, and custom fields.\n\n**Platform Identity** — A single platform-specific user ID linked to a contact (`cs_platform_identities`). One contact can have multiple: a Shopee buyer ID, a LINE user ID, and a phone number all pointing to the same person. Unique constraint: `(customer_id, platform_type, platform_user_id)`.\n\n**Identity Resolution** — The automatic process of finding or creating a contact when a message arrives. Looks up the platform user ID → if found, routes to the existing contact; if not found, creates a new contact + platform identity row.\n\n**Contact Merge** — Combining two contact records when they are discovered to be the same person. All platform identities, conversations, tickets, and memory from the secondary contact are re-pointed to the primary. The secondary is deleted.\n\n**Customer Memory** — AI-extracted persistent facts about a contact, stored as key-value pairs with categories (health, preference, interest, logistics, issue, feedback, communication). Example: `{category: \"health\", key: \"allergy\", value: \"Allergic to marine collagen\", confidence: 0.95}`.\n\n**Scope** — A `text[]` array on `merchant_credentials` that controls which modules share a credential. Valid values: `earn`, `cs`. A LINE OA credential with `scope = ''{earn,cs}''` is used by both the Earn module (for push messages) and CS (for conversations).\n\n**CRM User ID** — Optional link from a CS contact to a loyalty `user_master` record (`cs_contacts.crm_user_id`). Nullable — CS operates independently from loyalty. When linked, agents see loyalty data (tier, points) alongside conversation context.\n\n**Session Timeout** — How long a conversation stays open after the last message before auto-closing. Configurable per channel: 15 minutes to 48 hours.\n\n**Threading Interval** — Time window for grouping messages into the same conversation thread. Configurable: 1 hour to 72 hours. Messages arriving after the interval starts a new conversation.\n\n**Behavior Config** — Per-channel settings stored in `channel_config` jsonb: session timeout, threading interval, auto-reply toggle + message, AI toggle, voice preset override.", "content_format": "markdown", "knowledge_type": "key_concepts", "perspectives": ["customer_success", "general", "product", "testing"], "output_uses": ["agent_context", "product_docs", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L11 2. Key Concepts", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "8b2fa5e7b0e28bfebba7cfee4f38a7e4d5d2161b87798c7d52b9d81549979701", "truncated": false}, "is_active": true}, {"id": "7e322817-9494-5f8c-8357-f5b27b128453", "feature_slug": "cs-channels", "title": "6a. For Customer Success / Support", "content": "**Elevator pitch:** \"Channels let you connect all your messaging platforms — LINE, WhatsApp, marketplace chats, email, even voice — into one inbox. When a customer messages from Shopee and later from LINE, the system recognizes them as the same person and keeps their history unified.\"\n\n**Top support questions:**\n\n| Question | Answer |\n|---|---|\n| \"Channel shows disconnected\" | Credentials may be expired or revoked. Go to Channel Config, re-enter credentials, run Test connection. |\n| \"Same customer appears twice\" | Identity resolution created separate contacts. Go to Contact Detail, use the merge function to combine them. |\n| \"Customer memory is wrong\" | Go to Contact Detail → memory section, delete the incorrect entry. New extraction will produce updated facts on the next resolved conversation. |\n| \"Messages not arriving from Shopee\" | Check if the Shopee channel health is `healthy`. If `error`, re-authenticate via OAuth. Shopee requires whitelisted partner access. |\n| \"Can I use the same LINE account for CS and point notifications?\" | Yes — set the credential scope to `{earn,cs}`. Both modules share the same LINE OA credential. |", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["customer_success"], "output_uses": ["agent_context", "help_center", "training_material"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L165 6. Perspectives / 6a. For Customer Success / Support", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "f316471bd0610519e616c1f697315245e7ee68b18a341912b06932cdb0569df9", "truncated": false}, "is_active": true}, {"id": "a263a40b-9096-5108-864a-807551dbe95e", "feature_slug": "cs-channels", "title": "1. Overview", "content": "CS Channels is the multi-channel infrastructure that connects customer conversations from external messaging platforms into a unified inbox. Merchants connect channels — LINE, WhatsApp, Facebook Messenger, Instagram, Shopee, Lazada, TikTok Shop, email, web chat widget, and voice — and the system routes all inbound messages to a single workspace where AI or human agents respond.\n\nThe core problem channels solve: customers reach out from whichever platform they prefer, and the merchant needs one place to handle all of them. Beyond message routing, the channel layer handles identity resolution — mapping platform-specific identifiers (a Shopee buyer ID, a LINE user ID, a phone number) to a single contact record. One person messaging from LINE and Shopee is recognized as the same contact, with their conversation history and preferences unified.\n\nKey capabilities: (1) **10 channel types** across marketplace chat, messaging platforms, email, web widget, and voice; (2) **identity resolution** — automatic lookup and creation of unified contact records from platform-specific user IDs; (3) **customer memory** — AI-extracted persistent facts (preferences, allergies, communication style) attached to the contact and injected into future conversations; (4) **credential sharing via scope** — a single credential row (e.g., LINE Official Account) can serve both CS and Earn modules simultaneously.", "content_format": "markdown", "knowledge_type": "overview", "perspectives": ["general", "marketing", "product"], "output_uses": ["agent_context", "product_docs", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L3 1. Overview", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a2c192250e496efda2623968319cd0b20e80f5d08cf15ad29a712c6fa579ae0d", "truncated": false}, "is_active": true}, {"id": "03a5013b-ea6e-5ea8-aaf0-7e0899bae9b7", "feature_slug": "cs-channels", "title": "8. Related Features", "content": "| Feature | Connection to CS Channels |\n|---|---|\n| CS Conversations | Conversations are created on channels — each conversation has a `credential_id` linking to the channel. See `CS_Conversations.md`. |\n| CS Knowledge Base | Knowledge articles are referenced by AI during conversations on any channel. See `CS_Knowledge_Base.md`. |\n| CS Procedures | AI follows procedures (AOPs) during channel conversations. See `CS_Procedures.md`. |\n| Loyalty (Currency/Tier) | `crm_user_id` bridges CS contacts to loyalty users, enriching agent context with points and tier data. See `Currency.md`, `Tier.md`. |\n| Integration Hub | Channel credentials are stored in `merchant_credentials`, the same table used by the Integration Hub for all platform connections. See Integration Hub docs. |\n| Activity/Earning | Earn module can share channel credentials (e.g., LINE OA) via the `scope` array for push notifications. See `Activity_Based_Earning.md`. |", "content_format": "markdown", "knowledge_type": "related_features", "perspectives": ["general", "product"], "output_uses": ["agent_context", "product_docs"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L268 8. Related Features", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5204f75f27eed0affa52bfada6be0a7a68764726fbc3ba589e79cc7533cc0fe3", "truncated": false}, "is_active": true}, {"id": "bb6bb86f-a609-51cd-ae7c-f9b30819678e", "feature_slug": "cs-channels", "title": "6c. For Testers", "content": "**Config → expected behavior:**\n\n| Config | Expected Behavior |\n|---|---|\n| Channel health = `healthy` | Inbound messages from this platform are received and routed |\n| Channel health = `disconnected` | Inbound messages silently fail — no conversation created |\n| Channel `is_active = false` | Channel appears in list with \"Inactive\" badge, messages not processed |\n| `ai_enabled = true` | Messages route to AI agent before human assignment |\n| `auto_reply_enabled = true` | First inbound message triggers auto-reply text |\n| `scope = ''{earn}''` only | Channel does NOT appear in CS channel list (`cs_bff_get_channels` filters by `cs` scope) |\n| `scope = ''{earn,cs}''` | Channel appears in both CS channel list and Earn channel configs |\n| Session timeout = 30min | Conversation auto-closes 30 minutes after last message |\n\n**Identity resolution assertions:**\n\n- ASSERT: New platform user ID creates exactly 1 `cs_contacts` + 1 `cs_platform_identities` row\n- ASSERT: Known platform user ID returns existing contact, does not create duplicate\n- ASSERT: Merge re-points all platform identities from secondary to primary contact\n- ASSERT: Merge re-points all conversations and memory from secondary to primary\n- ASSERT: Merge deletes the secondary contact record\n- ASSERT: Platform identity uniqueness enforced: `(customer_id, platform_type, platform_user_id)`\n\n**Customer memory assertions:**\n\n- ASSERT: Memory extraction upserts on `(contact_id, merchant_id, category, key)` — new key inserts, existing key updates\n- ASSERT: Contradicting info overwrites old memory value\n- ASSERT: Memory with `expires_at` is auto-deleted after expiration\n- ASSERT: \"Forget me\" request deletes all memory for that contact (PDPA compliance)\n- ASSERT: Memory is isolated per contact per merchant — no cross-merchant leakage\n\n**Health status model:**\n\n| Status | Meaning | Transition |\n|---|---|---|\n| `disconnected` | Initial state or manually deactivated | → `healthy` (on successful test) |\n| `healthy` | Connection verified, messages flowing | → `degraded` / `error` (on failure detection) |\n| `degraded` | Intermittent issues detected | → `healthy` (on recovery) / `error` (on sustained failure) |\n| `error` | Broken connection, needs re-authentication | → `healthy` (after credential fix + test) |\n\n**Error states to test:**\n- Invalid credentials saved → test connection fails, health stays `disconnected`\n- OAuth token expired (marketplace) → messages stop arriving, health degrades to `error`\n- Concurrent messages from same platform user → exactly one contact created (no race condition duplicates)\n- Merge two contacts where secondary has conversations → all conversations accessible from primary\n- WhatsApp 24-hour window expired → outbound template messages required, free-form blocked\n- TikTok Shop 12-hour response SLA → alert if approaching deadline", "content_format": "markdown", "knowledge_type": "testing_guidance", "perspectives": ["testing"], "output_uses": ["agent_context", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L165 6. Perspectives / 6c. For Testers", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c9a56c6205ff8826f7d5c05a196120bf455180f9c83307ad8a3e3b5813e455c3", "truncated": false}, "is_active": true}, {"id": "01569c4a-0f1f-5d0e-9955-02151a4efa00", "feature_slug": "cs-channels", "title": "5. Customer Experience", "content": "**Note:** Customers interact via their native messaging platforms (LINE app, Shopee app, WhatsApp, etc.) — there is no dedicated CX Platform app for CS. The experience below describes what happens on the platform side.\n\n**Route map:**\n\n| Touchpoint | Platform | Identity Used |\n|---|---|---|\n| Marketplace chat | Shopee / Lazada / TikTok app | Buyer ID |\n| Messaging | LINE / WhatsApp / Facebook / Instagram app | Platform user ID / phone |\n| Email | Any email client | Email address |\n| Web widget | Merchant''s website | Session ID → email (via pre-chat form) |\n| Voice | Phone call | Phone number |\n\n### 5a. First Contact\n\n1. Customer sends a message or initiates a call on any connected platform\n2. Webhook delivers the message to the system with the platform user ID\n3. Identity resolution runs: lookup `cs_platform_identities` for this platform + user ID\n4. **New customer**: system creates a `cs_contacts` record + `cs_platform_identities` row, marks `is_new = true`\n5. **Returning customer**: system retrieves the existing contact, loads customer memory into the AI prompt\n6. Message is routed to the unified inbox as a new or continued conversation\n\n### 5b. Cross-Platform Recognition\n\n1. Customer who previously contacted via LINE now messages from Shopee\n2. System creates a new platform identity (Shopee buyer ID) under a new contact initially\n3. Auto-suggestion triggers if the Shopee buyer has the same phone or email as the LINE user: \"This Shopee buyer has same phone as this LINE user — link?\"\n4. Agent confirms → `cs_fn_merge_contacts` re-points all identities, conversations, and memory to the primary contact\n5. Future messages from either platform route to the same unified contact\n\n### 5c. Conversation Continuity\n\n1. Customer''s prior memory (preferences, issues, communication style) is injected into the AI context\n2. AI applies knowledge naturally — does not explicitly say \"I remember you told me...\"\n3. If the conversation resolves, a separate async process extracts new persistent facts from the transcript and stores them as customer memory", "content_format": "markdown", "knowledge_type": "user_experience", "perspectives": ["frontend", "marketing", "testing"], "output_uses": ["frontend_context", "marketing_content", "qa_testing"], "scope": "user_fe", "source_ref": "requirements/feature-docs/cs-channels.md#L128 5. Customer Experience", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "1798c1021bd21335031e14c4988cce7ddf12e5e229ae0831f1d2b4e9a57f754c", "truncated": false}, "is_active": true}, {"id": "b96b4387-d23a-59ff-97f3-66612bbda418", "feature_slug": "cs-channels", "title": "6b. For Marketing", "content": "**Value proposition:** Channels provide true omnichannel reach — customers are met on the platform they already use (LINE in Thailand, WhatsApp in Southeast Asia, marketplace chat for post-purchase). Identity resolution means a customer who buys on Shopee and messages on LINE is one person in the system, enabling consistent communication across touchpoints.\n\n**Channel coverage by use case:**\n- **Post-purchase support** — Shopee, Lazada, TikTok Shop chat (buyer messages about orders)\n- **Proactive outreach** — LINE push messages, WhatsApp template messages, email campaigns\n- **Real-time support** — Web widget (on merchant site), Facebook Messenger, Instagram DM\n- **Voice** — Inbound AI-powered calls with Thai/English speech recognition, outbound campaign calls\n\n**Metrics that matter:** Channel coverage (% of customer platforms connected), first response time per channel, resolution rate per channel, contact merge rate (identity unification effectiveness).", "content_format": "markdown", "knowledge_type": "value_proposition", "perspectives": ["marketing", "sales"], "output_uses": ["marketing_content", "proposal_content", "slide_generation"], "scope": "general", "source_ref": "requirements/feature-docs/cs-channels.md#L165 6. Perspectives / 6b. For Marketing", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-channels", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "71ab850c87677824edb79f6fefcc20bfd26cf8f6257097e65599fbf3d0022312", "truncated": false}, "is_active": true}, {"id": "d8ff17b4-c1a5-5c24-8cd9-e651b73dff8d", "feature_slug": "cs-channels-customers", "title": "Functions — Deployed", "content": "> **Note:** Table names changed from spec: `cs_customers` → `cs_contacts`, `cs_channels` → merged into `merchant_credentials` (credentials) + `cs_conversations.credential_id` (FK). Channel management uses `cs_bff_get_channels` / `cs_bff_upsert_channel`.\n>\n> **Scope column:** `merchant_credentials.scope` is `text[]` (array). A single credential row can serve multiple modules — e.g. `''{earn,cs}''` means both Earn and CS share the same credential. Functions filter with array overlap operator (`&&`). Valid scope values: `earn`, `cs`.\n>\n> **Integration Hub — Platform Model:** All integrations share `merchant_credentials` and are configured via `bff_get_integration_config` / `bff_upsert_integration_config`. The admin UI renders fields using a registry (`integration_type_master` → `integration_field_definitions`) with a 2-level hierarchy: **group** (section) → **fields**. Each app type is a separate `integration_key` and credential row (e.g. `line_login`, `line_messaging`). Types are grouped under `platform_key` for UI display (e.g. both appear under \"LINE\" platform). The `(merchant_id, service_name, environment)` unique constraint has been dropped to allow multiple credential rows per platform. `integration_type_master` has `platform_key`, `platform_name`, `platform_order` for grouping.\n\n### Pipeline\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_fn_resolve_contact` | Backend | `(p_merchant_id, p_platform_type, p_platform_user_id, p_display_name, p_email, p_phone)` | Find or create cs_contacts + cs_platform_identities. Returns contact_id, is_new. |\n| `cs_fn_merge_contacts` | Backend | `(p_primary_contact_id, p_secondary_contact_id, p_merchant_id)` | Re-point all platform_identities, conversations, tickets, memory from secondary → primary. Deletes secondary. |\n| `cs_fn_extract_customer_memory` | Backend | `(p_contact_id, p_merchant_id, p_conversation_id, p_memories jsonb)` | Batch upsert memory entries. Accepts array of {category, key, value, confidence}. Upserts on (contact_id, merchant_id, category, key). |\n\n### Admin BFF\n\n| Function | Type | Signature | Purpose |\n|---|---|---|---|\n| `cs_bff_get_channels` | BFF | `()` | List all credentials where `scope && ARRAY[''cs'']`. Returns id, credential_type, credential_name, scope, channel_config, webhook_url, is_active, health_status, conversation_count, last_activity. |\n| `cs_bff_upsert_channel` | BFF | `(p_credential_id uuid, p_credential_type text, p_credential_name text, p_credentials jsonb, p_channel_config jsonb, p_scope text[] DEFAULT ''{cs}'')` | Create or update a channel credential. On create: generates webhook_url, sets health_status=''disconnected''. On update: merges provided fields. |\n| `cs_bff_get_contact_details` | BFF | `(p_contact_id)` | Contact + all platform_identities + customer memory + recent 10 conversations. Agent workspace sidebar. |\n\n### Direct CRUD (Supabase client + RLS)\n\n- List contacts: direct table read with search\n- Update contact fields: direct table update\n- List/delete customer memory: direct table access\n\n### Schema note\n\n`cs_customer_memory` has a unique index on `(contact_id, merchant_id, category, key)` enabling the upsert pattern in `cs_fn_extract_customer_memory`.\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Channels.md#L134 Functions — Deployed", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-channels-customers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "a871ba1a6e2e281a7f847c603b6f29bdf338cb4535c38f0dda7c773781b02265", "truncated": false}, "is_active": true}, {"id": "3995a5c9-1536-5b49-b10a-d68782d457be", "feature_slug": "cs-channels-customers", "title": "Core Tables", "content": "### cs_channels\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `merchant_id` | uuid FK | |\n| `channel_type` | text | `shopee`, `lazada`, `tiktok`, `line`, `whatsapp`, `facebook`, `instagram`, `email`, `web_widget`, `voice` |\n| `display_name` | text | \"LINE OA: @mesoestetic_th\" |\n| `credentials` | jsonb | Encrypted. App keys, tokens, webhook secrets. |\n| `config` | jsonb | Rate limits, message format, session_timeout, threading_interval, voice_override |\n| `is_active` | boolean | default true |\n| `created_at` | timestamptz | |\n\n### cs_customers\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `merchant_id` | uuid FK | |\n| `display_name` | text | |\n| `email` | text | |\n| `phone` | text | |\n| `language` | text | Detected or stated |\n| `crm_user_id` | uuid | Link to loyalty user_master.id. Nullable. |\n| `tags` | text[] | |\n| `custom_fields` | jsonb | |\n| `first_contact_at` | timestamptz | |\n| `last_contact_at` | timestamptz | |\n| `created_at` | timestamptz | |\n\n### cs_platform_identities\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `customer_id` | uuid FK → cs_customers | |\n| `platform_type` | text | Same as channel_type values |\n| `platform_user_id` | text | Buyer ID, LINE UID, phone, email |\n| `platform_display_name` | text | |\n| `linked_at` | timestamptz | |\n\nUNIQUE: `(customer_id, platform_type, platform_user_id)`\n\n### cs_customer_memory\n\n| Column | Type | Notes |\n|---|---|---|\n| `id` | uuid PK | |\n| `customer_id` | uuid FK → cs_customers | |\n| `merchant_id` | uuid FK | |\n| `category` | text | `health`, `preference`, `interest`, `logistics`, `issue`, `feedback`, `communication` |\n| `key` | text | `allergy`, `delivery_preference`, `skin_type` |\n| `value` | text | Free-text: \"Allergic to marine collagen\" |\n| `confidence` | float | 0.0–1.0 |\n| `source_conversation_id` | uuid | |\n| `expires_at` | timestamptz | PDPA compliance. Nullable = no expiry. |\n| `created_at` | timestamptz | |\n\n---", "content_format": "markdown", "knowledge_type": "implementation_objects", "perspectives": ["implementation", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/CS_Channels.md#L8 Core Tables", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "objects", "feature_slug": "cs-channels-customers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "76959e3ba1fa1a2a522340bc9dbb7996fd0b0780471b327198207d5cee01b58a", "truncated": false}, "is_active": true}, {"id": "18611200-d7ae-5b54-a98a-a18d7c69ce51", "feature_slug": "cs-channels-customers", "title": "CS Channels & Customers Domain Reference", "content": "**Keywords:** channel, platform, shopee, lazada, tiktok, line, whatsapp, facebook, instagram, email, web_widget, voice, sms, twilio, phone_number, identity, identity_resolution, platform_identity, customer, cs_customer, cs_channels, cs_platform_identities, cs_customers, cs_phone_numbers, crm_user_id, memory, customer_memory, cs_customer_memory\n**Source:** `CS_Channels.md`\n**Tables:** `merchant_credentials` (scope text[] for module isolation), `cs_contacts`, `cs_platform_identities`, `cs_customer_memory`, `cs_phone_numbers` (provider-abstracted phone number inventory)\n| Function | Type | Purpose |\n|---|---|---|\n| `cs_bff_get_channels` | BFF | List credentials where `scope && ARRAY[''cs'']`. Returns config, health, conversation count. |\n| `cs_bff_upsert_channel` | BFF | Create or update channel credential. `p_scope text[] DEFAULT ''{cs}''`. |\n| `cs_bff_get_contact_details` | BFF | Contact + platform identities + memory + recent conversations |\n| `cs_fn_resolve_contact` | Backend | Find or create cs_contacts + cs_platform_identities |\n| `cs_fn_merge_contacts` | Backend | Re-point identities, conversations, memory from secondary → primary |\n| `cs_fn_extract_customer_memory` | Backend | Batch upsert memory entries post-resolution |\n| `cs_bff_get_phone_numbers` | BFF | List all active purchased phone numbers (provider-agnostic) |\n| `cs_bff_get_phone_number_details` | BFF | Single number details + 30-day stats |\n| `cs_fn_upsert_phone_number` | Backend | Insert/update phone number after provider purchase |\n| `cs_fn_release_phone_number` | Backend | Mark number released, clear webhooks |\n**Key Business Rules (summary):**\n- Channel credentials stored in `merchant_credentials` with `scope text[]` — e.g. `''{cs}''` or `''{earn,cs}''` for shared credentials\n- One `cs_customer` per real person per merchant (multiple platform identities map to one)\n- Identity resolution: webhook → platform_user_id lookup → existing or new customer\n- `crm_user_id` links to loyalty module (nullable — CS can operate independently)\n- Memory extracted asynchronously after conversation resolution\n- Memory governance: expiration (PDPA), right to erasure, per-brand isolation", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-channels-customers.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-channels-customers", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "c0e7b4286ac7e215838f034c932e1a03fcb1efb8c280438080328f615d51f7f1", "truncated": false}, "is_active": true}, {"id": "d8426109-482d-5649-b3f1-11b2ac7f85e5", "feature_slug": "cs-competitor-matrix", "title": "COMPETITOR FEATURE MATRIX", "content": "| Feature Area | Us | Sierra | Decagon | Intercom | Zendesk | Gorgias | Duoke | Zaapi | Respond.io |\n|---|---|---|---|---|---|---|---|---|---|\n| **Channels** | | | | | | | | | |\n| Shopee/Lazada/TikTok chat | Yes | No | No | No | No | No | Yes | Yes | No |\n| LINE OA | Yes | No | No | No | No | No | No | Yes | Yes |\n| Voice inbound | Yes | Yes | Yes | No | Yes (new) | No | No | No | WhatsApp |\n| Voice outbound | Yes | Yes | Yes | No | Yes (new) | No | No | No | WhatsApp |\n| Email | Yes | Yes | Yes | Yes | Yes | Yes | No | Yes | Yes |\n| Web widget | Yes | Yes | Yes | Yes | Yes | Yes | No | No | Yes |\n| **AI Agent** | | | | | | | | | |\n| Knowledge library | Yes | Yes | Yes | Yes | Yes | Yes | Add-on | Basic | Yes |\n| Knowledge gap detection | Yes | Yes | Yes | No | No | No | No | No | No |\n| Customer memory (cross-session) | Yes | Yes | Yes | Partial | Partial | No | No | No | No |\n| Multi-step reasoning | Yes | Yes | Yes | Yes | Yes | No | No | No | Partial |\n| Brand voice config | Yes | Yes | Yes | Yes | No | No | No | Yes | No |\n| Procedures (natural language) | Yes | Yes (Journeys) | Yes (AOPs) | Yes (Procedures) | Yes (Generative) | No | No | Scripts | No |\n| Guardrails and limits | Yes | Yes | Yes | Partial | Partial | No | No | No | No |\n| Supervisor verification model | Yes | Yes | No | No | No | No | No | No | No |\n| **Actions** | | | | | | | | | |\n| Cancel order | Yes | Yes | Yes | Via connector | Via action | Shopify | Yes | No | If wired |\n| Process refund | Yes | Yes | Yes | Via connector | Via action | Shopify | Yes | No | If wired |\n| Create voucher | Yes | N/A | N/A | Via connector | Via action | Shopify | No | No | If wired |\n| Custom API builder | Yes | SDK | Yes | Data Connectors | Action Builder | Custom Actions | No | No | HTTP Actions |\n| Computer use (browser) | Yes | No | Partial | No | No | No | No | No | No |\n| **Automation** | | | | | | | | | |\n| Rules engine | Yes | Yes | Yes | Yes (Workflows) | Yes (Triggers) | Yes | Basic | Basic | Yes |\n| Intent detection | Yes | Yes | Yes | Yes | Yes | Yes (23+) | Basic | No | No |\n| Sentiment detection | Yes | Yes | Yes | No | No | No | Yes (96%) | No | Yes |\n| SLA management | Yes | Yes | Yes | Yes | Yes | Yes | No | No | Yes |\n| **Human Agent** | | | | | | | | | |\n| Live Assist (AI drafts) | Yes | Yes | Partial | No | Yes | No | No | No | Yes |\n| Conversation summary | Yes | Yes | Yes | Partial | Yes | No | No | No | No |\n| Action suggestions | Yes | Yes | Yes | No | No | No | No | No | No |\n| Real-time translation | Yes | No | No | No | No | No | Yes | No | No |\n| **QA and Insights** | | | | | | | | | |\n| Auto QA (100%) | Yes | Yes | Yes | Partial | Yes | No | No | No | No |\n| CSAT surveys | Yes | Yes | Yes | Yes | Yes | Yes | No | No | No |\n| Knowledge gap report | Yes | Yes | Yes | No | No | No | No | No | No |\n| Agent coaching insights | Yes | Yes | No | No | Yes | No | No | No | No |\n| Sentiment trends | Yes | Yes | Yes | No | No | No | Yes | No | Yes |\n| **Testing** | | | | | | | | | |\n| Agent simulator | Yes | Yes | Yes | Yes (Simulations) | No | No | No | Yes (test chat) | No |\n| Automated test suites | Yes | Yes (auto-gen) | Yes | Yes | No | No | No | No | No |\n| A/B experimentation | Yes | Yes | No | No | No | No | No | No | No |\n| **Proactive** | | | | | | | | | |\n| Broadcast messaging | Yes | No | No | Yes | No | No | No | Yes | Yes |\n| Event-triggered outreach | Yes | Yes | Yes (Proactive) | Yes | Yes | No | Yes | No | Yes |\n| Outbound voice | Yes | Yes | Yes | No | Yes (new) | No | No | No | No |\n| **Traditional Helpdesk** | | | | | | | | | |\n| Custom ticket fields | Yes | No | No | Yes | Yes | Yes | No | No | Yes |\n| Views and filters | Yes | No | No | Yes | Yes | Yes | No | No | Yes |\n| Parent-child tickets | Yes | No | No | Yes | Yes | No | No | No | No |\n| Merge / split / link | Yes | No | No | Yes | Yes | Yes | No | No | No |\n| SLA policies | Yes | Yes | Yes | Yes | Yes | Yes | No | No | Yes |\n| Business hours / holidays | Yes | No | No | Yes | Yes | Yes | No | No | Yes |\n| Time tracking | Yes | No | No | No | Yes | No | No | No | No |\n| Knowledge base (customer) | Yes | Yes | Yes | Yes | Yes | No | No | No | No |\n| Customer portal | Yes | No | No | Yes | Yes | No | No | No | No |\n| Contact form / web form | Yes | Yes | Yes | Yes | Yes | Yes | No | No | Yes |\n| Canned responses / macros | Yes | No | No | Yes | Yes | Yes | Yes | Yes | Yes |\n| Collision detection | Yes | No | No | Yes | Yes | No | No | No | No |\n| Bulk actions | Yes | No | No | Yes | Yes | Yes | No | No | Yes |\n| Side conversations | Yes | No | No | Yes | Yes | No | No | No | No |\n| **Enterprise** | | | | | | | | | |\n| Multi-tenant | Yes | Yes | Yes | Yes | Yes | Yes | Yes | Yes | Yes |\n| Computer use agent | Yes | No | Partial | No | No | No | No | No | No |\n| On-premise deploy | Future | Yes | No | No | No | No | No | No | No |\n| Thai language optimized | Yes | No | No | Partial | Partial | No | Partial | Yes | Partial |\n| CRM/Loyalty native bridge | Yes | No | No | No | No | No | No | No | No |\n\n---", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["product", "technical"], "output_uses": ["agent_context", "technical_docs"], "scope": "general", "source_ref": "requirements/CS_Competitor_Matrix.md#L5 COMPETITOR FEATURE MATRIX", "metadata": {"source_doc_type": "requirement_deep_source", "source_priority": "requirement_doc", "review_status": "generated", "selection_reason": "overview", "feature_slug": "cs-competitor-matrix", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5b7c0e686abb355390d1a2bb2a8572c2d322d97092d2347ed124632780d7f462", "truncated": false}, "is_active": true}, {"id": "845b1b4f-e2d4-5e0f-82bd-baf89d7820dd", "feature_slug": "cs-competitor-matrix", "title": "CS Competitor Matrix Domain Reference", "content": "**Keywords:** sierra, decagon, intercom, zendesk, gorgias, duoke, zaapi, respond_io, oho_chat, zwiz, kore_ai, gowajee, competitor, benchmark\n**Source:** `CS_Competitor_Matrix.md`", "content_format": "markdown", "knowledge_type": "technical_overview", "perspectives": ["implementation", "product", "technical"], "output_uses": ["agent_context", "implementation_brief", "technical_docs"], "scope": "be", "source_ref": "requirements/domains/cs-competitor-matrix.md", "metadata": {"source_doc_type": "domain_reference", "source_priority": "domain_pointer", "review_status": "generated", "feature_slug": "cs-competitor-matrix", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "3db876a234c2496c90edffba8a58267225eca63bed6dfa6fe92586182279c3dd", "truncated": false}, "is_active": true}, {"id": "690e2638-8276-568b-ab33-ca0a8b706bee", "feature_slug": "cs-conversations", "title": "4. Agent Journey", "content": "**Repo:** `Rocket-CRM/loyalty-admin`\n\n**Route map:**\n\n| Page Name | Current Route | BFF / Data Source |\n|---|---|---|\n| CS Inbox | `/cs-inbox` | `cs_bff_list_conversations()`, `cs_bff_get_conversation_details()` |\n| CS Brand Config | `/cs-brand-config` | Brand config BFF |\n| CS Analytics | `/cs-analytics` | Analytics queries |\n\n### 4a. Work the Inbox\n\n1. Open **CS Inbox** — 3-panel layout fills the viewport (no page header)\n2. **Left panel** shows conversation list with view tabs: My Open, Unassigned, All Open, Overdue, Resolved — each with badge count\n3. Search bar filters conversations by customer name or message content\n4. Each conversation row shows: customer initials avatar, customer name, last message preview (prefixed \"You:\" or \"AI:\" for non-customer senders), channel badge (LINE, Shopee, WA, etc.), time-ago, unread count badge, priority color strip (red = urgent, yellow = high)\n5. Click a conversation (or press J/K to navigate) → **center panel** loads the chat thread\n6. **Thread header** shows: customer avatar + name, channel badge, status, priority dropdown, Assign/Transfer/Resolve buttons, sidebar toggle\n\n### 4b. Respond to a Conversation\n\n1. Read the message history in the chat thread (customer messages, AI replies, system events displayed chronologically)\n2. Type a reply in the composer at the bottom → send (delivers to customer''s channel)\n3. To add an internal note: switch to note mode → type → send (note is visible only to agents, never delivered to customer)\n4. To access knowledge base articles or canned responses: toggle the **Content Panel** (slides out within the thread area)\n\n### 4c. Manage a Conversation\n\n1. **Assign**: click \"Assign\" button (or press A) → modal with agent list → select agent → toast \"Assigned to [name]\"\n2. **Change priority**: use the priority dropdown in the thread header (Urgent / High / Normal / Low)\n3. **Resolve**: click \"Resolve\" button (or press E) → conversation moves to Resolved view → toast \"Conversation resolved\"\n4. **Reopen**: on a resolved/closed conversation, click \"Reopen\" (or press E) → returns to Open\n5. **Create ticket**: from the customer sidebar, click \"Create Ticket\" → modal to fill ticket details → links ticket to this conversation\n6. **Update tags**: edit tags in the customer sidebar\n7. **View customer profile**: sidebar shows customer details, loyalty member link, past conversations, linked tickets\n\n### 4d. Keyboard Shortcuts\n\n| Key | Action |\n|---|---|\n| J / K | Navigate conversations down / up |\n| E | Resolve (or Reopen if already resolved) |\n| A | Open assign modal |\n| Cmd/Ctrl + Shift + S | Toggle customer sidebar |", "content_format": "markdown", "knowledge_type": "admin_journey", "perspectives": ["customer_success", "frontend", "testing"], "output_uses": ["frontend_context", "qa_testing", "training_material"], "scope": "admin_fe", "source_ref": "requirements/feature-docs/cs-conversations.md#L74 4. Agent Journey", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "afe30ba0b66fca3ab619a2a6dddbc5434e16431513b54cfcf216aa2c979afb2b", "truncated": false}, "is_active": true}, {"id": "686c9c9d-7161-5408-836b-8fea8966ce43", "feature_slug": "cs-conversations", "title": "7. Business Rules", "content": "**Rule:** One active conversation per customer per channel. A new inbound message on a channel with an existing open/pending conversation is appended to that conversation.\n**Example:** Customer sends \"Hello\" then \"Where''s my order?\" on LINE 5 minutes apart → both messages in same conversation.\n\n**Rule:** Threading interval determines reopen vs. new creation. Within the interval, resolved/closed conversations reopen. After the interval, a new conversation is created.\n**Example:** LINE threading_interval = 48h. Resolved conversation, customer messages 36h later → reopens. Messages 60h later → new conversation.\n\n**Rule:** Session timeout applies only to active conversations (open/pending). If the conversation is idle beyond the timeout, the system closes it as inactive and creates a new conversation on the next message.\n**Example:** Web chat timeout = 30 min. No messages for 45 min → old conversation closed. Customer types again → new conversation.\n\n**Rule:** Marketplace channels follow the platform''s native threading. Shopee, Lazada, and TikTok Shop provide their own `conversation_id` — the system maps 1:1 and does not apply its own threading logic.\n**Example:** Shopee buyer sends messages across different days in the same Shopee chat thread → all map to one conversation.\n\n**Rule:** Internal notes are never delivered to the customer''s channel. They exist only in the inbox thread for agent coordination.\n**Example:** Agent adds note \"Checking with warehouse team\" → customer sees nothing new in their LINE chat.\n\n**Rule:** Conversation events are append-only. Every status change, assignment, message receipt, and action execution is logged as an immutable event. Events cannot be modified or deleted.\n**Example:** Conversation assigned → reassigned → resolved generates three separate event records.\n\n**Rule:** Message deduplication prevents duplicate AI/system messages. If an identical message (same conversation + sender_type + content + message_type) is inserted within 60 seconds, the existing message_id is returned.\n**Example:** Retry logic triggers duplicate AI response → second insert returns the first message_id, no duplicate in thread.\n\n**Rule:** Topic change mid-conversation does not split the thread. AI creates a new ticket for the second issue while continuing the same conversation.\n**Example:** Customer asks about a refund, then asks about store hours → one conversation, two tickets.\n\n**Rule:** Voice calls always create a new conversation. There is no threading interval for voice — each call is a distinct conversation.", "content_format": "markdown", "knowledge_type": "business_rules", "perspectives": ["customer_success", "product", "technical", "testing"], "output_uses": ["agent_context", "product_docs", "qa_testing"], "scope": "general", "source_ref": "requirements/feature-docs/cs-conversations.md#L232 7. Business Rules", "metadata": {"source_doc_type": "feature_guide", "source_priority": "feature_guide", "review_status": "generated", "feature_slug": "cs-conversations", "generation_batch": "feature_knowledge_seed_20260511T091258Z", "content_sha256": "5922b17b432af45faca60e9dabd7195628505e03bbc88f5497ea03c313c86872", "truncated": false}, "is_active": true}]'::jsonb) as x(
    id uuid,
    feature_slug text,
    title text,
    content text,
    content_format text,
    knowledge_type text,
    perspectives text[],
    output_uses text[],
    scope text,
    source_ref text,
    metadata jsonb,
    is_active boolean
  )
),
resolved_blocks as (
  select
    b.id,
    f.id as feature_item_id,
    b.title,
    b.content,
    b.content_format,
    b.knowledge_type::internal_knowledge_type as knowledge_type,
    b.perspectives::internal_knowledge_perspective[] as perspectives,
    b.output_uses::internal_knowledge_output_use[] as output_uses,
    b.scope::internal_knowledge_scope as scope,
    b.source_ref,
    b.metadata,
    coalesce(b.is_active, true) as is_active
  from input_blocks b
  join public.internal_knowledge_feature_items f on lower(f.slug) = lower(b.feature_slug)
)
insert into public.internal_knowledge_blocks (
  id, feature_item_id, title, content, content_format, knowledge_type,
  perspectives, output_uses, scope, source_ref, metadata, is_active, updated_at
)
select
  id,
  feature_item_id,
  title,
  content,
  content_format,
  knowledge_type,
  perspectives,
  output_uses,
  scope,
  source_ref,
  metadata,
  is_active,
  now()
from resolved_blocks
on conflict (id) do update set
  feature_item_id = excluded.feature_item_id,
  title = excluded.title,
  content = excluded.content,
  content_format = excluded.content_format,
  knowledge_type = excluded.knowledge_type,
  perspectives = excluded.perspectives,
  output_uses = excluded.output_uses,
  scope = excluded.scope,
  source_ref = excluded.source_ref,
  metadata = public.internal_knowledge_blocks.metadata || excluded.metadata,
  is_active = excluded.is_active,
  updated_at = now();

commit;
